/// Counts how many characters in `text` are ASCII uppercase letters ('A'..='Z').
///
/// Characters that are not in the ASCII range 'A'..='Z' (including lowercase,
/// digits, symbols, whitespace, and non-ASCII letters) are not counted.
///
/// Total function: works for any input vector (including empty).
pub fn count_uppercase(text: &Vec<char>) -> u64 {
    text.iter()
        .filter(|&&c| c.is_ascii_uppercase())
        .count() as u64
}

#[cfg(test)]
mod tests {
    use super::count_uppercase;

    #[test]
    fn empty() {
        let v: Vec<char> = vec![];
        assert_eq!(count_uppercase(&v), 0);
    }

    #[test]
    fn basic_mixed() {
        let v: Vec<char> = "aAZ 0!Z".chars().collect();
        // Uppercase ASCII letters: 'A', 'Z', 'Z' => 3
        assert_eq!(count_uppercase(&v), 3);
    }

    #[test]
    fn non_ascii_not_counted() {
        let v: Vec<char> = "ÄÖÜAZß".chars().collect();
        // 'Ä','Ö','Ü','ß' are non-ASCII; only 'A','Z' count.
        assert_eq!(count_uppercase(&v), 2);
    }

    #[test]
    fn all_ascii_uppercase() {
        let v: Vec<char> = ('A'..='Z').collect();
        assert_eq!(count_uppercase(&v), 26);
    }
}